#[derive(Debug, Clone, Copy, PartialEq)]
enum Light {
    Red,
    Yellow,
    Green,
    Flashing,
}

impl Light {
    fn next(self) -> Light {
        self
    }
}

fn main() {
    let mut light = Light::Red;
    for _ in 0..3 {
        println!("{light:?} -> {:?}", light.next());
        light = light.next();
    }
}
